			title = "Предания горы",
			text = [=[• Один каменщик Стальгорна высек памятник солдату Салли Баллу, погибшему далеко от дома, из прекрасного камня, привезенного из разоренного {link:lordaeron}Лордерон{/link}а. Король заплатил за него сам.
• {link:gorn}Горн{/link}ые стрелки, что гибнут в снегах {link:dun-morogh}Дун Морог{/link}а, возвращаются домой ружьями, на прикладах которых вырезаны их имена.]=],
		},
	},
})

Translate("ruRU", "the-great-forge", {
	title = "Великая Кузня",
	aliases = { "Великая Кузня" },
	sections = {
		{
			title = "Обзор",
			text = [=[Великая Кузня занимает центральный зал {link:ironforge}Стальгорн{/link}а. Расплавленный металл льется с высоты в {link:ogres}огр{/link}омные чаши, а вокруг них кузнецы города работают у наковален, которые никогда не остывают. Жар и свет кузни достигают каждого квартала, а стук ее молотов — тот звук, который {link:dwarves}дворф{/link}ы называют домом. По ее кольцу толпятся торговцы, наставники и гонцы, а грифоны города прилетают и улетают с террасы неподалеку. Нет в городе места оживленнее, и нет места любимее.]=],
		},
	},
})

Translate("ruRU", "the-commons", {
	title = "Общий зал",
	sections = {
		{
			title = "Обзор",
			text = [=[Общий зал — торговый квартал {link:ironforge}Стальгорн{/link}а. Здесь стоят Хранилище Стальгорна, где под охраной лежат богатства города и его гостей, большой аукционный зал и таверна, которую держит хозяин Огнехмель. Сюда приходят купцы всех народов {link:alliance}Альянс{/link}а, и квартал гудит от торга с первого часа до последнего. Путники, проведшие долгое время в дороге, идут в таверну за теплым очагом и крепким элем, прежде чем отправиться дальше.]=],
		},
	},
})

Translate("ruRU", "hall-of-explorers", {
	title = "Зал Исследователей",
	aliases = { "Собрание исследователей" },
	sections = {
		{
			title = "Обзор",
			text = [=[Зал Исследователей — дом {link:explorers-league}Лиги исследователей{/link}. В его галереях хранятся реликвии, привезенные из руин со всего мира, в его библиотеке — книги и карты Лиги, а его ученые спорят об истинном происхождении {link:dwarves}дворф{/link}ийского народа. Председательствует здесь верховный исследователь {link:high-explorer-magellas}Магеллас{/link}. {link:advisor-belgrum}Советник Белграм{/link}, историк {link:historian-karnik}Карник{/link} и изыскатель Штормпайк ведут в этом чертоге свои дела, и новости с раскопок в {link:badlands}Бесплодных землях{/link} и {link:loch-modan}Лок Модане{/link} первыми приходят сюда.]=],
		},
	},
})

Translate("ruRU", "tinker-town", {
	title = "Город Механиков",
	sections = {
		{
			title = "Обзор",
			text = [=[Город Механиков — квартал, который {link:magni-bronzebeard}король Магни{/link} отдал {link:gnomes}гном{/link}ам после падения {link:gnomeregan}Гномреган{/link}а. Он лязгает шестернями и шипит паром, а его мастерские забиты недостроенными устройствами. Верховный механик {link:gelbin-mekkatorque}Меггакрут{/link} держит здесь свой двор в изгнании. Из Города Механиков Подземный поезд идет глубоко под землей в {link:stormwind-city}Штормград{/link}, а механики Гномрегана посылают добровольцев обратно в свой потерянный город — спасти то, что удастся.]=],
		},
	},
})

Translate("ruRU", "the-mystic-ward", {
	title = "Квартал Мистиков",
