			text = [=[Военный квартал — крепость внутри крепости. В его Зале Оружия воинов {link:ironforge}Стальгорн{/link}а обучает Мурен Штормпайк, который учит, что воин никогда не поворачивается к врагу спиной. Солдаты короля проходят здесь выучку, прежде чем выступить на фронты {link:alliance}Альянс{/link}а. Это суровое место, и {link:dwarves}дворф{/link}ы, что служат в нем, гордятся этим.]=],
		},
	},
})

Translate("ruRU", "high-seat", {
	title = "Высокий трон",
	aliases = { "зал Высокого трона" },
	sections = {
		{
			title = "Обзор",
			text = [=[Высокий трон — тронный зал {link:ironforge}Стальгорн{/link}а, поднятый над западными залами города. Здесь {link:magni-bronzebeard}король Магни Бронзобород{/link} держит двор под охраной гвардейцев Железной королевской стражи. Сенаторы Стальгорна приходят и уходят по делам державы, а королевский историк хранит память королевства близ трона. Дверь в боковой стене зала, долго стоявшая запечатанной, теперь открыта. За ней тропа ведет вниз, в {link:old-ironforge}Старый Стальгорн{/link}.]=],
		},
	},
})

Translate("ruRU", "old-ironforge", {
	title = "Старый Стальгорн",
