		{
			title = "Значение",
			text = [=[Мурадин был связан с домом {link:lordaeron}Лордерона{/link} не одним лишь союзом. Он был наставником в ратном деле юного принца {link:arthas-menethil}Артаса Менетила{/link}, и они дружили. Эти узы сделали его свидетелем первых шагов принца к гибели. Они же стоили ему жизни — так, по крайней мере, считают в {link:ironforge}Стальгорн{/link}е.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он служил {link:alliance}Альянс{/link}у и был известен при дворах человеческих королевств.
• Он обучал принца {link:lordaeron}Лордерон{/link}а искусству меча и молота.
• Он возглавил поход {link:dwarves}дворф{/link}ов в Нордскол на поиски легендарного рунного клинка, называемого Ледяной Скорбью.
• Он сражался рядом с принцем против нежити в ледяных пустошах.]=],
		},
		{
			title = "Путь на север",
			text = [=[Отряд {link:dwarves}дворф{/link}ов долго искал Ледяную Скорбь в Нордсколе, прежде чем им встретился {link:arthas-menethil}Артас{/link}, который преследовал повелителя ужаса через море. Дворфы и принц объединили силы против нежити. Мурадин тревожился все сильнее, глядя на своего прежнего ученика. Артас сжег собственные корабли, чтобы его люди не могли вернуться домой, и ненависть к врагу стала единственным, ради чего он, казалось, жил.

{link:nak}Нак{/link}онец они нашли клинок в ледяной пещере, запечатанный во льду и охраняемый. Мурадин прочел вырезанное там предостережение и умолял принца оставить меч. Принц не послушал. Когда Артас освободил меч, лед разлетелся на куски, и один осколок сразил дворфа. Артас взял Ледяную Скорбь и пошел дальше без него.]=],
		},
		{
			title = "В Стальгорне",
			text = [=[{link:dwarves}Дворфы{/link} помнят его как героя {link:alliance}Альянс{/link}а и брата своего короля. Его утрата — еще одна тяжесть, которую несет {link:magni-bronzebeard}Магни{/link}, рядом с войском вдали от дома и дочерью, которую забрали дворфы Черного Железа. В залах {link:ironforge}Стальгорн{/link}а его имя произносят с печалью — и с той упрямой гордостью, которую дворфы хранят для тех, кто пал, делая то, что считал правильным.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Что стало с ним после того дня, в {link:ironforge}Стальгорн{/link}е не знают. Его народ верит, что он погиб во льдах. Ни одна летопись, известная {link:dwarves}дворф{/link}ам, не говорит иного.]=],
		},
	},
	bonds = {
		{ id = "magni-bronzebeard", name = "Магни Бронзобород", note = "его брат" },
		{ id = "brann-bronzebeard", name = "Бранн Бронзобород", note = "его брат" },
		{ id = "arthas-menethil", name = "Артас Менетил", note = "его ученик" },
	},
})

Translate("ruRU", "brann-bronzebeard", {
	title = "Бранн Бронзобород",
	subtitle = "Исследователь Лиги исследователей",
	found = "Странствует вдали от Стальгорна",
	allegiance = "Королевство Стальгорн · Лига исследователей",
	aliases = { "Бранн" },
	sections = {
		{
			title = "Обзор",
			text = [=[Бранн Бронзобород — младший брат короля {link:magni-bronzebeard}Магни{/link}. Там, где Магни взял корону, а {link:muradin-bronzebeard}Мурадин{/link} — молот, Бранн взял карту и фонарь. Он самый знаменитый исследователь {link:explorers-league}Лиги исследователей{/link}, {link:dwarves}дворф{/link}, который охотнее заночует в руинах титанов, чем в королевской постели.]=],
		},
		{
			title = "Значение",
			text = [=[Бранн — живой дух великого вопроса Лиги: откуда пришли {link:dwarves}дворф{/link}ы? Всю жизнь он ищет ответ в древних местах мира, и его имя открывает двери, закрытые для менее известных искателей. Ученые Лиги в Зале Исследователей продолжают его дело, пока он странствует.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он исследовал руины по всем {link:eastern-kingdoms}Восточным королевствам{/link} и за их пределами в поисках истоков {link:dwarves}дворф{/link}ов.
• Его числят среди ведущих членов Лиги исследователей.]=],
		},
		{
			title = "Великий вопрос",
			text = [=[Вопрос, который им движет, — тот самый, что задает вся Лига: вправду ли {link:dwarves}дворф{/link}ы были сотворены титанами из камня? В его отсутствие его товарищи подошли к ответу ближе, чем когда-либо. Из глубин {link:uldaman}Ульдаман{/link}а они вынесли записи о трудах титанов, и эти записи указывают на еще более великие хранилища в пустынях юга. Именно таким открытиям Бранн отдал свою жизнь.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Странствия увели его далеко от {link:ironforge}Стальгорн{/link}а, и никто в городе не скажет, где он сейчас. О его путешествиях в залах Высокого трона слышат одни лишь слухи. Эта запись сообщает только то, что известно наверняка.]=],
		},
	},
	bonds = {
		{ id = "magni-bronzebeard", name = "Магни Бронзобород", note = "его старший брат" },
		{ id = "muradin-bronzebeard", name = "Мурадин Бронзобород", note = "его брат" },
		{ id = "high-explorer-magellas", name = "Верховный исследователь Магеллас", note = "возглавляет Лигу в его отсутствие" },
	},
})

Translate("ruRU", "gelbin-mekkatorque", {
	title = "Гелбин Меггакрут",
	subtitle = "Верховный механик, король гномов",
	found = "Город Механиков, Стальгорн",
	hint = "Отыщите верховного механика в Городе Механиков.",
	allegiance = "Изгнанники Гномрегана · Альянс",
	aliases = { "Меггакрут", "верховный механик Меггакрут", "Гелбин", "верховный механик Гелбин Меггакрут" },
	sections = {
		{
			title = "Обзор",
			text = [=[Гелбин Меггакрут — верховный механик {link:gnomes}гном{/link}ов, король народа, потерявшего свое королевство. Он правил в {link:gnomeregan}Гномрегане{/link}, когда город был велик. Теперь он правит из мастерской в Городе Механиков, гость {link:dwarves}дворф{/link}ов, а большая часть его народа мертва, отравлена или рассеяна. Он не утратил ни ума, ни воли. Он намерен вернуться домой.]=],
		},
		{
			title = "Значение",
			text = [=[Меггакрут удерживает {link:gnomes}гном{/link}ов вместе. Без него изгнанники были бы толпой беженцев. С ним они остаются народом, у которого есть место среди народов {link:alliance}Альянса{/link} и право на свой город, от которого они никогда не отказывались.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он возглавлял {link:gnomes}гном{/link}ов {link:gnomeregan}Гномреган{/link}а как верховный механик.
• Когда под городом поднялись {link:troggs}трогг{/link}и, он в отчаянной попытке очищения обратил против них искусство самих гномов, и город был отравлен.
• Он привел уцелевших в {link:ironforge}Стальгорн{/link} и сделал {link:tinker-town}Город Механиков{/link} их домом.
• Он посылает добровольцев обратно в Гномреган — вернуть оставленное и нанести удар по предателю, который удерживает город.]=],
		},
		{
			title = "Падение города",
			text = [=[Ни одна летопись не сообщает, в каком году {link:troggs}трогг{/link}и поднялись из глубин под {link:gnomeregan}Гномреган{/link}ом. Они пришли в великом множестве, и город не смог их сдержать. Меггакрут решил истребить их оружием, которое создали сами {link:gnomes}гном{/link}ы. Оно убивало троггов, но убило и великое множество гномов и оставило город пропитанным ядом. Многие из выживших превратились в больных и безумных прокаженных. Остальные бежали в снега {link:dun-morogh}Дун Морог{/link}а.]=],
		},
		{
			title = "Двор в изгнании",
			text = [=[В Городе Механиков народ верховного механика не прекратил трудиться. Мастер-изобретатель Сверхискр надеется починить своего бедного техбота, чей разум перевернулся при падении города. Мастер-механик Чугунная Труба собирает отряды, чтобы вернуть жизненно важные записи из терминалов города. Мастеру Клокморту Гайкокруту нужны детали, которые никто не вспомнил захватить при бегстве. Каждое такое поручение — маленький шаг обратно в {link:gnomeregan}Гномреган{/link}, и Меггакрут поощряет их все.]=],
		},
	},
	chapters = {
		{
			title = "Великое предательство",
			hint = "Сразите предателя, который правит Гномреганом.",
			text = [=[Меггакрут доверял {link:gnomes}гном{/link}у Сикко Термоштепселю. Он и представить не мог, что тот предаст его и весь гномский народ, и до сих пор не понимает почему: власть и богатство со временем и так пришли бы к предателю. Теперь изменник сидит в руинах, король ничего. Когда пришла весть, что {link:mekgineer-thermaplugg}Термоштепсель{/link} пал, Меггакрут позволил себе мрачную шутку, а затем обратил мысли к тому дню, когда гномы вернут свой город.]=],
		},
	},
	mentions = {
		{ text = "«Спасение данных»" },
		{ text = "«Спасите мозг Техбота!»" },
		{ text = "«Необходимые искусственные компоненты»" },
	},
	bonds = {
		{ id = "mekgineer-thermaplugg", name = "Мехинженер Термоштепсель", note = "предатель" },
		{ id = "magni-bronzebeard", name = "Магни Бронзобород", note = "его хозяин и союзник" },
		{ id = "razzle-sprysprocket", name = "Раззл Шустрошестер", note = "один из его народа, ищущий лекарство" },
	},
})

Translate("ruRU", "royal-historian-archesonus", {
	title = "Королевский историк Архезонус",
	subtitle = "Королевский историк Стальгорна",
	found = "Высокий трон, возле трона",
	hint = [=[Поговорите с историком, которая хранит память королевства возле трона.]=],
	allegiance = "Королевство Стальгорн",
	aliases = { "Архезонус" },
	sections = {
		{
			title = "Обзор",
			text = [=[Королевский историк Архезонус хранит память {link:ironforge}Стальгорн{/link}а возле трона короля {link:magni-bronzebeard}Магни{/link}. Всякий, кто спросит, может услышать от нее историю королевства. Серьезнее всего она рассказывает повесть о {link:dwarves}дворф{/link}ах Черного Железа и о городе {link:ruins-of-thaurissan}Тауриссан{/link}, который сгорел.]=],
		},
		{
			title = "Значение",
			text = [=[Архезонус — голос прошлого {link:ironforge}Стальгорн{/link}а. {link:dwarves}Дворфы{/link} — народ долгой памяти, и в зале Высокого трона у этой памяти есть хранительница. Ее знания о клане Черного Железа стали насущными, ибо старый враг королевства снова пришел в движение.]=],
		},
		{
			title = "Деяния",
			text = [=[• Она учит истории {link:ironforge}Стальгорн{/link}а тех, кто приходит к Высокому трону.
• Она посылает искателей в {link:ruins-of-thaurissan}Руины Тауриссана{/link} в Пылающих степях — прочесть оставшиеся там реликвии.]=],
		},
	},
	chapters = {
		{
			title = "Повесть о городе Тауриссан",
			hint = [=[Попросите королевского историка рассказать историю клана Черного Железа.]=],
			text = [=[Архезонус начинает издалека — с тех времен, когда у {link:dwarves}дворф{/link}ов Черного Железа был собственный город. {link:ruins-of-thaurissan}Тауриссан{/link} стоял в зеленом краю, который ныне зовется Пылающими степями, и в те дни кланы дворфов воевали друг с другом. Потом страшный взрыв уничтожил его, и земля на мили вокруг выгорела дотла. Что вызвало взрыв, признаёт она, не может сказать ни один историк. Выжившие дворфы Черного Железа ушли в гору и начали заново. Из пепла поднялась Вершина Черной горы, а {link:the-cauldron}Котлован{/link} Тлеющего ущелья был укреплен. Вскоре пошли шепотки о древнем зле, что правит королевством Черного Железа изнутри. Ее рассказ кончается настоящим. Дворфов Черного Железа с каждым годом все чаще видят на поверхности. Они возвели крепости в {link:badlands}Бесплодных землях{/link}, послали большие отряды в {link:uldaman}Ульдаман{/link} и даже напали на плотину {link:loch-modan}Лок Модана{/link}.]=],
		},
		{
			title = "Тлеющие руины",
			hint = [=[Прочтите реликвии погибшего города и принесите их воспоминания домой.]=],
			text = [=[Реликвии разрушенного города хранят воспоминания, и те, кто их касается, уносят их с собой. Существо из чистого пламени. Восемь {link:dwarves}дворф{/link}ов Черного Железа за обрядом. Один из них в конце — в одиночестве, на коленях среди семерых мертвых перед столпом огня. Архезонус выслушала эти воспоминания и сказала, что они многое объясняют и что узнать предстоит еще гораздо больше.]=],
		},
	},
	mentions = {
		{ text = "«Тлеющие {link:ruins-of-thaurissan}руины Тауриссана{/link}»" },
	},
	bonds = {
		{ id = "magni-bronzebeard", name = "Магни Бронзобород", note = "ее король" },
	},
})

Translate("ruRU", "high-explorer-magellas", {
	title = "Верховный исследователь Магеллас",
	subtitle = "Верховный исследователь Лиги исследователей",
	found = "Зал Исследователей",
	hint = "Поговорите с верховным исследователем в Зале Исследователей.",
	allegiance = "Лига исследователей",
	aliases = { "Магеллас" },
	sections = {
		{
			title = "Обзор",
			text = [=[Верховный исследователь Магеллас возглавляет {link:explorers-league}Лигу исследователей{/link} из Зала Исследователей. Он занятой {link:dwarves}дворф{/link} и дает посетителям это понять. И все же никого в {link:ironforge}Стальгорн{/link}е настоящее открытие не волнует сильнее, и когда такое ложится на его стол, вся его важность вылетает в окно.]=],
		},
		{
			title = "Значение",
			text = [=[При нем Лига ищет ответ на вопрос, который для нее важнее всего: доказательство того, что {link:dwarves}дворф{/link}ы были сотворены из камня титанами, которых старые записи называют Творцами. Он верит, что это доказательство, возможно, уже в пределах досягаемости.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он руководит экспедициями Лиги и награждает тех, кто ей служит, из хранилища Лиги.
• Он изучает уменьшенные {link:lore-keeper-of-norgannon}Диски Норганнона{/link}, привезенные из {link:uldaman}Ульдаман{/link}а.
• Он обращает взор Лиги к {link:valley-of-the-watchers}Ульдум{/link}у, далеко на юге, в {link:tanaris}Танарис{/link}е.]=],
		},
	},
	chapters = {
		{
			title = "Платиновые диски",
			hint = "Принесите Лиге находку из глубин Ульдамана.",
			text = [=[Когда перед ним положили уменьшенную копию Дисков Норганнона, Магеллас спросил, где ее нашли, потом спросил еще раз и не мог поверить ответам. Он назвал ее находкой века. Если диски говорят то, что он думает, они раз и навсегда решат старый вопрос о происхождении {link:dwarves}дворф{/link}ов.]=],
		},
		{
			title = "Ульдум манит",
			hint = [=[Следуйте за дисками к вратам Ульдума и доложите об увиденном.]=],
			text = [=[Диски привели к запечатанным вратам {link:valley-of-the-watchers}Ульдум{/link}а, где еще один каменный страж говорил о пластинах, которых недостает. Магеллас согласился со своими учеными, что поиски должны подождать, пока не станет ясно, где искать. Он пообещал, что, когда придет время, Лига пошлет в поле те же руки.]=],
		},
	},
	mentions = {
		{ text = "«Платиновые диски»" },
		{ text = "«Знамения {link:valley-of-the-watchers}Ульдум{/link}а»" },
	},
	bonds = {
		{ id = "historian-karnik", name = "Историк Карник", note = "его ученый" },
		{ id = "brann-bronzebeard", name = "Бранн Бронзобород", note = "самый знаменитый исследователь Лиги" },
	},
})

Translate("ruRU", "advisor-belgrum", {
	title = "Советник Белграм",
	subtitle = "Советник короля",
	found = "Зал Исследователей",
	hint = "Найдите советника короля среди ученых в Зале Исследователей.",
	allegiance = "Королевство Стальгорн · Лига исследователей",
	aliases = { "Белграм" },
	sections = {
		{
			title = "Обзор",
			text = [=[Советник Белграм говорит в Зале Исследователей от имени короля. Когда пришла весть, что клан Тенегорн из числа {link:dwarves}дворф{/link}ов Черного Железа убил в Бесплодных землях исследователя Тяжелоступа, именно Белграм приказал ударить по их крепости и именно Белграм поклялся, что поиски титановой Таблички Воли, которые вел Тяжелоступ, будут доведены до конца.]=],
